/**
 * Handles JSX spread operator in the snapshot system.
 *
 * Spread operators in JSX (e.g., <div {...props}>) are transformed into
 * optimized attribute updates at compile time, avoiding runtime object spreads.
 */

import { retainWorkletCtx } from '@lynx-js/react/worklet-runtime/bindings';
import type { Element, Worklet, WorkletRefImpl } from '@lynx-js/react/worklet-runtime/bindings';

import type { BackgroundSnapshotInstance } from './backgroundSnapshot.js';
import { updateEvent } from './event.js';
import { updateGesture } from './gesture.js';
import {
  getListItemPlatformInfoFromIndexedValue,
  platformInfoAttributes,
  updateListItemPlatformInfo,
} from './platformInfo.js';
import { transformRef, updateRef } from './ref.js';
import { updateWorkletEvent } from './workletEvent.js';
import { updateWorkletRef } from './workletRef.js';
import { transformAttrName } from '../../shared/attribute-name.js';
import { isDirectOrDeepEqual, isEmptyObject } from '../../utils.js';
import { retainGestureWorkletCtx } from '../gesture/processGesture.js';
import type { GestureKind } from '../gesture/types.js';
import { ListUpdateInfoRecording } from '../list/listUpdateInfo.js';
import { __pendingListUpdates } from '../list/pendingListUpdates.js';
import type { SnapshotInstance } from '../snapshot/snapshot.js';

// eslint-disable-next-line regexp/no-unused-capturing-group
const eventRegExp = /^(([A-Za-z-]*):)?(bind|catch|capture-bind|capture-catch|global-bind)([A-Za-z]+)$/;
const eventTypeMap: Record<string, string> = {
  bind: 'bindEvent',
  catch: 'catchEvent',
  'capture-bind': 'capture-bind',
  'capture-catch': 'capture-catch',
  'global-bind': 'global-bindEvent',
};
function retainSpreadWorkletCtx(newValue: Record<string, unknown>, oldValue: Record<string, unknown>): void {
  let match: RegExpMatchArray | null = null;
  for (const key in newValue) {
    const value = newValue[key];
    if (value === oldValue[key]) {
      continue;
    }

    if (key.endsWith(':ref')) {
      if (key.slice(0, -4) === 'main-thread' && value && (value as Worklet)._wkltId) {
        retainWorkletCtx(value as Worklet);
      }
    } else if (key.endsWith(':gesture')) {
      if (key.slice(0, -8) === 'main-thread') {
        retainGestureWorkletCtx(value as GestureKind);
      }
    } else if (
      (match = eventRegExp.exec(key)) && match[2] === 'main-thread' && value !== null && value !== undefined
      && typeof value === 'object'
    ) {
      retainWorkletCtx(value as Worklet);
    }
  }
}

function updateSpread(
  snapshot: SnapshotInstance,
  index: number,
  oldValue: Record<string, unknown> | undefined | null,
  elementIndex: number,
  isListItem = false,
): void {
  oldValue ??= {};
  let newValue: Record<string, unknown> = snapshot.__values![index] as Record<string, unknown>; // compiler guarantee this must be an object;

  const list = snapshot.parentNode;
  if (list?.__snapshot_def.isListHolder) {
    const oldPlatformInfo = getListItemPlatformInfoFromIndexedValue(oldValue, true);
    const platformInfo = getListItemPlatformInfoFromIndexedValue(newValue, true);
    if (!isDirectOrDeepEqual(oldPlatformInfo, platformInfo)) {
      if (__pendingListUpdates.values) {
        (__pendingListUpdates.values[list.__id] ??= new ListUpdateInfoRecording(list)).onSetAttribute(
          snapshot,
          platformInfo,
          oldPlatformInfo,
        );
      }
      snapshot.__listItemPlatformInfo = platformInfo;

      // The fakeSnapshot is missing `__parent`, so no `ListUpdateInfoRecording#onSetAttribute` will be called
      const fakeSnapshot = {
        __values: {
          get [index]() {
            return platformInfo;
          },
        },
        __id: snapshot.__id,
        __elements: snapshot.__elements,
      } as SnapshotInstance;
      updateListItemPlatformInfo(fakeSnapshot, index, oldPlatformInfo, elementIndex);
    }
  } else if (isListItem) {
    // Only seed list-item platform info before the snapshot is attached to a list holder.
    // Non-platform spread attributes continue through the normal update loop below.
    const platformInfo = getListItemPlatformInfoFromIndexedValue(newValue, true);
    snapshot.__listItemPlatformInfo = platformInfo;
  }

  if ('__spread' in newValue) {
    // first screen
    newValue = transformSpread(snapshot, index, newValue);
    snapshot.__values![index] = newValue;
  }

  if (!snapshot.__elements) {
    retainSpreadWorkletCtx(newValue, oldValue);
    return;
  }

  const dataset: Record<string, unknown> = {};
  let match: RegExpMatchArray | null = null;
  for (const key in newValue) {
    const v = newValue[key];
    if (v !== oldValue[key]) {
      if (key === 'className') {
        __SetClasses(snapshot.__elements[elementIndex]!, v as string);
      } else if (key === 'style') {
        if (!isDirectOrDeepEqual(v, oldValue[key])) {
          __SetInlineStyles(snapshot.__elements[elementIndex]!, v);
        }
      } else if (key === 'id') {
        __SetID(snapshot.__elements[elementIndex]!, v as string);
      } else if (key.startsWith('data-')) {
        // collected below
      } else if (key === 'ref') {
        const fakeSnapshot = {
          __values: {
            get [index]() {
              return v;
            },
            set [index](value: unknown) {
              // Modifications to the ref value should be reflected in the corresponding position of the spread.
              newValue[key] = value;
            },
          },
          __id: snapshot.__id,
          __elements: snapshot.__elements,
        } as SnapshotInstance;
        updateRef(fakeSnapshot, index, oldValue[key] as string | null, elementIndex);
      } else if (key.endsWith(':ref')) {
        snapshot.__worklet_ref_set ??= new Set();
        const fakeSnapshot = {
          __values: {
            get [index]() {
              return v;
            },
          },
          __id: snapshot.__id,
          __elements: snapshot.__elements,
          __worklet_ref_set: snapshot.__worklet_ref_set,
        } as SnapshotInstance;
        updateWorkletRef(
          fakeSnapshot,
          index,
          oldValue[key] as WorkletRefImpl<Element> | Worklet | null | undefined,
          elementIndex,
          key.slice(0, -4),
        );
      } else if (key.endsWith(':gesture')) {
        const workletType = key.slice(0, -8);
        const fakeSnapshot = {
          __values: {
            get [index]() {
              return v;
            },
          },
          __id: snapshot.__id,
          __elements: snapshot.__elements,
        } as SnapshotInstance;
        updateGesture(fakeSnapshot, index, oldValue[key], elementIndex, workletType);
      } else if ((match = eventRegExp.exec(key))) {
        const workletType = match[2];
        const eventType = eventTypeMap[match[3]!]!;
        const eventName = match[4]!;
        const fakeSnapshot = {
          __values: {
            get [index]() {
              return v;
            },
            set [index](value: unknown) {
              // Modifications to the event value should be reflected in the corresponding position of the spread.
              newValue[key] = value;
            },
          },
          __id: snapshot.__id,
          __elements: snapshot.__elements,
        } as SnapshotInstance;
        if (workletType) {
          updateWorkletEvent(
            fakeSnapshot,
            index,
            oldValue[key] as Worklet,
            elementIndex,
            workletType,
            eventType,
            eventName,
          );
        } else {
          updateEvent(fakeSnapshot, index, oldValue[key], elementIndex, eventType, eventName, key);
        }
      } else if (platformInfoAttributes.has(key)) {
        // ignore
      } else {
        __SetAttribute(snapshot.__elements[elementIndex]!, key, v);
      }
    }

    // collect data regardless of whether it has changed
    if (key.startsWith('data-')) {
      dataset[key.slice(5)] = v;
    }
  }

  let hasOldDataset = false;
  for (const key in oldValue) {
    if (!(key in newValue)) {
      if (key === 'className') {
        __SetClasses(snapshot.__elements[elementIndex]!, '');
      } else if (key === 'style') {
        __SetInlineStyles(snapshot.__elements[elementIndex]!, '');
      } else if (key === 'id') {
        __SetID(snapshot.__elements[elementIndex]!, null);
      } else if (key.startsWith('data-')) {
        // collected below
      } else if (key === 'ref') {
        const fakeSnapshot = {
          __values: {
            get [index]() {
              return undefined;
            },
            set [index](value: unknown) {
              // Modifications to the ref value should be reflected in the corresponding position of the spread.
              newValue[key] = value;
            },
          },
          __id: snapshot.__id,
          __elements: snapshot.__elements,
        } as SnapshotInstance;
        updateRef(fakeSnapshot, index, oldValue[key] as string | null, elementIndex);
      } else if (key.endsWith(':ref')) {
        snapshot.__worklet_ref_set ??= new Set();
        const fakeSnapshot = {
          __values: {
            get [index]() {
              return undefined;
            },
          },
          __id: snapshot.__id,
          __elements: snapshot.__elements,
          __worklet_ref_set: snapshot.__worklet_ref_set,
        } as SnapshotInstance;
        updateWorkletRef(
          fakeSnapshot,
          index,
          oldValue[key] as WorkletRefImpl<Element> | Worklet | null | undefined,
          elementIndex,
          key.slice(0, -4),
        );
      } else if (key.endsWith(':gesture')) {
        const workletType = key.slice(0, -8);
        const fakeSnapshot = {
          __values: {
            get [index]() {
              return undefined;
            },
          },
          __id: snapshot.__id,
          __elements: snapshot.__elements,
        } as SnapshotInstance;
        updateGesture(fakeSnapshot, index, oldValue[key], elementIndex, workletType);
      } else if ((match = eventRegExp.exec(key))) {
        const workletType = match[2];
        const eventType = eventTypeMap[match[3]!]!;
        const eventName = match[4]!;
        const fakeSnapshot = {
          __values: {
            get [index]() {
              return undefined;
            },
            set [index](value: unknown) {
              newValue[key] = value;
            },
          },
          __id: snapshot.__id,
          __elements: snapshot.__elements,
        } as SnapshotInstance;
        if (workletType) {
          updateWorkletEvent(
            fakeSnapshot,
            index,
            oldValue[key] as Worklet,
            elementIndex,
            workletType,
            eventType,
            eventName,
          );
        } else {
          updateEvent(fakeSnapshot, index, oldValue[key], elementIndex, eventType, eventName, key);
        }
      } else if (platformInfoAttributes.has(key)) {
        // ignore
      } else {
        __SetAttribute(snapshot.__elements[elementIndex]!, key, null);
      }
    }

    // collect data regardless of whether it has changed
    if (key.startsWith('data-')) {
      hasOldDataset = true;
    }
  }

  // TODO: compare dataset before commit it to native?
  if (hasOldDataset || !isEmptyObject(dataset)) {
    __SetDataset(snapshot.__elements[elementIndex]!, dataset);
  }
}

function transformSpread(
  snapshot: BackgroundSnapshotInstance | SnapshotInstance,
  index: number,
  spread: Record<string, unknown>,
): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  let hasNoFlattenAttributes = false;
  for (const key in spread) {
    let value = spread[key];
    if (key === '__spread') {}
    else if (key === 'class' || key === 'className') {
      value ??= '';
      result['className'] = value;
    } else if (key === 'ref') {
      if (__LEPUS__) {
        result[key] = value ? 1 : undefined;
      } else {
        result[key] = transformRef(value)?.__ref;
      }
    } else if (key === '__self' || key === '__source') {
      // for react debug tools
    } else if (typeof value === 'function') {
      const transformedKey = transformAttrName(key);
      result[transformedKey] = `${snapshot.__id}:${index}:${key}`;
    } else {
      const transformedKey = transformAttrName(key);
      if (!hasNoFlattenAttributes) {
        // Keep the switch for a small fixed list; consider Set.has if the list grows significantly.
        switch (transformedKey) {
          case 'name':
          case 'clip-radius':
          case 'overlap':
          case 'exposure-scene':
          case 'exposure-id':
            hasNoFlattenAttributes = true;
        }
      }
      result[transformedKey] = value;
    }
  }

  if (hasNoFlattenAttributes) {
    result['flatten'] = false;
  }
  return result;
}

export { transformSpread, updateSpread };
